-- Approved two-package corporate membership. Forward-only; never apply automatically.
BEGIN;
UPDATE public.packages SET price=5500,active=TRUE WHERE code='CORPORATE_SUBSCRIPTION_30_DAY';
INSERT INTO public.packages(code,name,price,seller_type,duration_days,active)
SELECT 'CORPORATE_PLUS_30_DAY','Corporate Plus',25000,'CORPORATE',30,TRUE
WHERE NOT EXISTS(SELECT 1 FROM public.packages WHERE code='CORPORATE_PLUS_30_DAY');

ALTER TABLE public.corporate_profiles ADD COLUMN IF NOT EXISTS active_package_code TEXT;
UPDATE public.corporate_profiles
SET active_package_code='CORPORATE_SUBSCRIPTION_30_DAY'
WHERE subscription_status='ACTIVE' AND active_package_code IS NULL;
CREATE TABLE public.corporate_membership_periods(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),corporate_profile_id UUID NOT NULL REFERENCES public.corporate_profiles(id) ON DELETE CASCADE,package_id UUID NOT NULL REFERENCES public.packages(id),package_code TEXT NOT NULL CHECK(package_code IN('CORPORATE_SUBSCRIPTION_30_DAY','CORPORATE_PLUS_30_DAY')),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,payment_id UUID REFERENCES public.payments(id),granted_by_profile_id UUID REFERENCES public.character_profiles(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(starts_at<ends_at),CHECK((payment_id IS NULL)<>(granted_by_profile_id IS NULL)));
CREATE UNIQUE INDEX uq_membership_period_payment ON public.corporate_membership_periods(payment_id) WHERE payment_id IS NOT NULL;

ALTER TABLE public.listing_credits ALTER COLUMN payment_id DROP NOT NULL;
ALTER TABLE public.listing_credits ADD COLUMN usage_scope TEXT NOT NULL DEFAULT 'NEW_OR_REPUBLISH' CHECK(usage_scope IN('NEW_LISTING_ONLY','NEW_OR_REPUBLISH')),ADD COLUMN grant_source TEXT NOT NULL DEFAULT 'PURCHASE' CHECK(grant_source IN('PURCHASE','MEMBERSHIP_PLUS')),ADD COLUMN grant_sequence INTEGER,ADD COLUMN membership_period_id UUID REFERENCES public.corporate_membership_periods(id) ON DELETE RESTRICT;
DROP INDEX IF EXISTS public.uq_listing_credits_payment;
CREATE UNIQUE INDEX uq_listing_credits_paid_payment ON public.listing_credits(payment_id) WHERE grant_source='PURCHASE' AND payment_id IS NOT NULL;
CREATE UNIQUE INDEX uq_listing_credits_membership_grant ON public.listing_credits(membership_period_id,grant_sequence) WHERE grant_source='MEMBERSHIP_PLUS';
ALTER TABLE public.listing_credits ADD CONSTRAINT chk_listing_credit_grant_shape CHECK((grant_source='PURCHASE' AND payment_id IS NOT NULL AND membership_period_id IS NULL AND grant_sequence IS NULL) OR (grant_source='MEMBERSHIP_PLUS' AND payment_id IS NULL AND membership_period_id IS NOT NULL AND grant_sequence>0));

CREATE TABLE public.corporate_boost_credits(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),corporate_profile_id UUID NOT NULL REFERENCES public.corporate_profiles(id) ON DELETE CASCADE,membership_period_id UUID REFERENCES public.corporate_membership_periods(id) ON DELETE RESTRICT,payment_id UUID REFERENCES public.payments(id),grant_source TEXT NOT NULL CHECK(grant_source IN('MEMBERSHIP_PLUS','PURCHASE')),grant_sequence INTEGER,used_listing_id UUID REFERENCES public.listings(id) ON DELETE SET NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK((used_listing_id IS NULL)=(used_at IS NULL)),CHECK((grant_source='PURCHASE' AND payment_id IS NOT NULL AND membership_period_id IS NULL AND grant_sequence IS NULL) OR (grant_source='MEMBERSHIP_PLUS' AND payment_id IS NULL AND membership_period_id IS NOT NULL AND grant_sequence>0)));
CREATE UNIQUE INDEX uq_corporate_boost_paid_payment ON public.corporate_boost_credits(payment_id) WHERE grant_source='PURCHASE';
CREATE UNIQUE INDEX uq_corporate_boost_membership_grant ON public.corporate_boost_credits(membership_period_id,grant_sequence) WHERE grant_source='MEMBERSHIP_PLUS';
CREATE INDEX idx_corporate_boost_available ON public.corporate_boost_credits(corporate_profile_id,grant_source,created_at) WHERE used_at IS NULL;

CREATE OR REPLACE FUNCTION public.apply_corporate_membership_period(p_store_id UUID,p_package_code TEXT,p_payment_id UUID DEFAULT NULL,p_admin_id UUID DEFAULT NULL) RETURNS public.corporate_membership_periods LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s public.corporate_profiles%ROWTYPE;p public.packages%ROWTYPE;r public.corporate_membership_periods%ROWTYPE;at TIMESTAMPTZ:=NOW();from_at TIMESTAMPTZ;to_at TIMESTAMPTZ;
BEGIN
 IF (p_payment_id IS NULL)=(p_admin_id IS NULL) THEN RAISE EXCEPTION 'Exactly one grant source is required';END IF;
 IF p_payment_id IS NOT NULL THEN SELECT * INTO r FROM public.corporate_membership_periods m WHERE m.payment_id=p_payment_id;IF FOUND THEN RETURN r;END IF;END IF;
 SELECT * INTO p FROM public.packages WHERE code=p_package_code AND active AND seller_type='CORPORATE' AND duration_days=30 FOR SHARE;
 IF NOT FOUND OR p.code NOT IN('CORPORATE_SUBSCRIPTION_30_DAY','CORPORATE_PLUS_30_DAY') THEN RAISE EXCEPTION 'INVALID_MEMBERSHIP_PACKAGE';END IF;
 SELECT * INTO s FROM public.corporate_profiles WHERE id=p_store_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'APPROVED' OR s.moderation_status<>'ACTIVE' OR s.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'CORPORATE_NOT_ELIGIBLE';END IF;
 IF s.subscription_status='ACTIVE' AND s.subscription_expires_at>at AND COALESCE(s.active_package_code,'CORPORATE_SUBSCRIPTION_30_DAY') IS DISTINCT FROM p.code THEN RAISE EXCEPTION 'ACTIVE_PACKAGE_CHANGE_NOT_ALLOWED';END IF;
 from_at:=GREATEST(at,COALESCE(s.subscription_expires_at,at));to_at:=from_at+INTERVAL '1 month';
 INSERT INTO public.corporate_membership_periods(corporate_profile_id,package_id,package_code,starts_at,ends_at,payment_id,granted_by_profile_id) VALUES(s.id,p.id,p.code,from_at,to_at,p_payment_id,p_admin_id) RETURNING * INTO r;
 IF p.code='CORPORATE_PLUS_30_DAY' THEN
  INSERT INTO public.listing_credits(profile_id,package_id,credit_type,corporate_profile_id,amount,status,usage_scope,grant_source,grant_sequence,membership_period_id) SELECT s.owner_profile_id,p.id,'CORPORATE',s.id,0,'AVAILABLE','NEW_LISTING_ONLY','MEMBERSHIP_PLUS',n,r.id FROM generate_series(1,20)n;
  INSERT INTO public.corporate_boost_credits(corporate_profile_id,membership_period_id,grant_source,grant_sequence) SELECT s.id,r.id,'MEMBERSHIP_PLUS',n FROM generate_series(1,3)n;
 END IF;
 UPDATE public.corporate_profiles SET subscription_status='ACTIVE',subscription_expires_at=to_at,current_period_start=CASE WHEN from_at=at THEN at ELSE current_period_start END,current_period_end=to_at,active_package_code=p.code,monthly_boost_credits=CASE WHEN p.code='CORPORATE_SUBSCRIPTION_30_DAY' THEN 3 ELSE monthly_boost_credits END,boost_credits=CASE WHEN p.code='CORPORATE_SUBSCRIPTION_30_DAY' THEN 3+purchased_boost_credits ELSE boost_credits END,updated_at=at WHERE id=s.id;
 PERFORM public.transition_corporate_membership_listings(s.id,'RESUME');RETURN r;
END $$;

CREATE OR REPLACE FUNCTION public.consume_corporate_boost(p_actor_profile_id UUID,p_listing_id UUID,p_payment_mode TEXT DEFAULT 'REQUIRE_CREDIT') RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s public.corporate_profiles%ROWTYPE;l public.listings%ROWTYPE;c public.corporate_boost_credits%ROWTYPE;at TIMESTAMPTZ:=NOW();until_at TIMESTAMPTZ;bypass BOOLEAN:=p_payment_mode='TEST_BYPASS';source TEXT;
BEGIN
 IF p_payment_mode NOT IN('REQUIRE_CREDIT','TEST_BYPASS') THEN RETURN jsonb_build_object('success',false,'code','LISTING_NOT_ELIGIBLE','error','Geçersiz ödeme modu.');END IF;
 SELECT * INTO l FROM public.listings WHERE id=p_listing_id FOR UPDATE;IF NOT FOUND OR l.status<>'ACTIVE' OR l.expires_at IS NULL OR l.expires_at<=at THEN RETURN jsonb_build_object('success',false,'code','LISTING_NOT_ELIGIBLE');END IF;IF l.is_featured AND l.featured_until IS NOT NULL AND l.featured_until>at THEN RETURN jsonb_build_object('success',false,'code','ALREADY_BOOSTED');END IF;
 IF bypass AND l.seller_type='INDIVIDUAL' AND l.seller_profile_id=p_actor_profile_id THEN until_at:=at+INTERVAL '24 hours';UPDATE public.listings SET is_featured=true,featured_until=until_at,updated_at=at WHERE id=l.id;RETURN jsonb_build_object('success',true,'remaining_boosts',0,'monthly_boost_credits',0,'purchased_boost_credits',0,'featured_until',until_at);END IF;
 SELECT * INTO s FROM public.corporate_profiles WHERE owner_profile_id=p_actor_profile_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR l.seller_type<>'CORPORATE' OR l.corporate_profile_id IS DISTINCT FROM s.id THEN RETURN jsonb_build_object('success',false,'code','LISTING_NOT_OWNED');END IF;
 IF s.status<>'APPROVED' OR s.moderation_status<>'ACTIVE' THEN RETURN jsonb_build_object('success',false,'code','LISTING_NOT_ELIGIBLE');END IF;
 IF s.subscription_status<>'ACTIVE' OR s.subscription_expires_at IS NULL OR s.subscription_expires_at<=at THEN RETURN jsonb_build_object('success',false,'code','SUBSCRIPTION_INACTIVE');END IF;
 IF NOT bypass THEN
  SELECT * INTO c FROM public.corporate_boost_credits WHERE corporate_profile_id=s.id AND grant_source='MEMBERSHIP_PLUS' AND used_at IS NULL ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;
  IF FOUND THEN UPDATE public.corporate_boost_credits SET used_listing_id=l.id,used_at=at WHERE id=c.id;source:='MEMBERSHIP_PLUS';
  ELSIF s.monthly_boost_credits>0 THEN UPDATE public.corporate_profiles SET monthly_boost_credits=monthly_boost_credits-1,boost_credits=(monthly_boost_credits-1)+purchased_boost_credits,updated_at=at WHERE id=s.id RETURNING * INTO s;source:='MONTHLY';
  ELSIF s.purchased_boost_credits>0 THEN UPDATE public.corporate_profiles SET purchased_boost_credits=purchased_boost_credits-1,boost_credits=monthly_boost_credits+(purchased_boost_credits-1),updated_at=at WHERE id=s.id RETURNING * INTO s;source:='PURCHASED';
  ELSE RETURN jsonb_build_object('success',false,'code','NO_BOOST_CREDITS','error','Kullanılabilir Boost Krediniz bulunmuyor.');END IF;
 END IF;
 until_at:=at+INTERVAL '24 hours';UPDATE public.listings SET is_featured=true,featured_until=until_at,updated_at=at WHERE id=l.id;
 RETURN jsonb_build_object('success',true,'credit_id',c.id,'grant_source',source,'remaining_boosts',s.boost_credits,'monthly_boost_credits',s.monthly_boost_credits,'purchased_boost_credits',s.purchased_boost_credits,'featured_until',until_at);
END $$;

-- Membership rows roll over indefinitely, but require any active corporate membership when consumed.
CREATE OR REPLACE FUNCTION public.complete_sanboard_payment(p_order_id TEXT,p_external_payment_id TEXT DEFAULT NULL) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE pay public.payments%ROWTYPE;pkg public.packages%ROWTYPE;credit public.listing_credits%ROWTYPE;period public.corporate_membership_periods%ROWTYPE;at TIMESTAMPTZ:=NOW();
BEGIN
 SELECT * INTO pay FROM public.payments WHERE order_id=p_order_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Ödeme kaydı bulunamadı.');END IF;
 IF pay.status='SUCCESS' AND pay.entitlement_applied_at IS NOT NULL THEN IF p_external_payment_id IS NOT NULL AND pay.external_payment_id IS NOT NULL AND p_external_payment_id<>pay.external_payment_id THEN RETURN jsonb_build_object('success',false,'error','Ödeme farklı işlem kimliğiyle tamamlanmış.');END IF;SELECT * INTO credit FROM public.listing_credits WHERE payment_id=pay.id;SELECT * INTO period FROM public.corporate_membership_periods WHERE payment_id=pay.id;RETURN jsonb_build_object('success',true,'credit',to_jsonb(credit),'membership_period',to_jsonb(period));END IF;
 IF p_external_payment_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.payments WHERE external_payment_id=p_external_payment_id AND id<>pay.id) THEN RETURN jsonb_build_object('success',false,'error','Sağlayıcı işlemi daha önce kullanılmış.');END IF;
 SELECT * INTO pkg FROM public.packages WHERE id=pay.package_id;IF NOT FOUND OR NOT pkg.active OR pay.amount<>pkg.price OR pay.amount<=0 THEN RETURN jsonb_build_object('success',false,'error','Paket veya tutar doğrulanamadı.');END IF;
 IF pay.entitlement_type='CORPORATE_SUBSCRIPTION' AND pkg.code IN('CORPORATE_SUBSCRIPTION_30_DAY','CORPORATE_PLUS_30_DAY') THEN period:=public.apply_corporate_membership_period(pay.corporate_profile_id,pkg.code,pay.id,NULL);
 ELSIF pay.entitlement_type='LISTING_CREDIT' AND ((pkg.code='STANDARD_7_DAY' AND pkg.seller_type='INDIVIDUAL') OR (pkg.code='CORPORATE_14_DAY' AND pkg.seller_type='CORPORATE')) THEN
  IF pkg.code='CORPORATE_14_DAY' AND NOT EXISTS(SELECT 1 FROM public.corporate_profiles WHERE id=pay.corporate_profile_id AND owner_profile_id=pay.profile_id AND subscription_status='ACTIVE' AND subscription_expires_at>at AND moderation_status='ACTIVE') THEN RETURN jsonb_build_object('success',false,'error','Kurumsal üyelik aktif değil.');END IF;
  INSERT INTO public.listing_credits(profile_id,payment_id,package_id,credit_type,corporate_profile_id,amount,status,usage_scope,grant_source) VALUES(pay.profile_id,pay.id,pay.package_id,CASE WHEN pkg.seller_type='CORPORATE' THEN 'CORPORATE' ELSE 'INDIVIDUAL' END,CASE WHEN pkg.seller_type='CORPORATE' THEN pay.corporate_profile_id END,pay.amount,'AVAILABLE','NEW_OR_REPUBLISH','PURCHASE') ON CONFLICT DO NOTHING RETURNING * INTO credit;IF credit.id IS NULL THEN SELECT * INTO credit FROM public.listing_credits WHERE payment_id=pay.id;END IF;
 ELSE RETURN jsonb_build_object('success',false,'error','Paket ve entitlement uyumsuz.');END IF;
 UPDATE public.payments SET status='SUCCESS',external_payment_id=COALESCE(external_payment_id,p_external_payment_id),paid_at=COALESCE(paid_at,at),entitlement_applied_at=COALESCE(entitlement_applied_at,at) WHERE id=pay.id;
 RETURN jsonb_build_object('success',true,'credit',to_jsonb(credit),'membership_period',to_jsonb(period));
END $$;

CREATE OR REPLACE FUNCTION public.grant_corporate_subscription(p_corporate_profile_id UUID,p_admin_profile_id UUID,p_package_code TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE period public.corporate_membership_periods%ROWTYPE;s public.corporate_profiles%ROWTYPE;BEGIN IF NOT EXISTS(SELECT 1 FROM public.character_profiles WHERE id=p_admin_profile_id AND role='ADMIN') THEN RETURN jsonb_build_object('success',false,'error','Yönetici yetkisi doğrulanamadı.');END IF;BEGIN period:=public.apply_corporate_membership_period(p_corporate_profile_id,p_package_code,NULL,p_admin_profile_id);EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success',false,'error',SQLERRM);END;SELECT * INTO s FROM public.corporate_profiles WHERE id=p_corporate_profile_id;RETURN jsonb_build_object('success',true,'dealer',to_jsonb(s),'period',to_jsonb(period));END $$;
CREATE OR REPLACE FUNCTION public.grant_corporate_subscription(p_corporate_profile_id UUID,p_admin_profile_id UUID) RETURNS JSONB LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$SELECT public.grant_corporate_subscription(p_corporate_profile_id,p_admin_profile_id,'CORPORATE_SUBSCRIPTION_30_DAY')$$;

CREATE OR REPLACE FUNCTION public.complete_sanboard_boost_payment(p_order_id TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE pay public.payments%ROWTYPE;pkg public.packages%ROWTYPE;s public.corporate_profiles%ROWTYPE;at TIMESTAMPTZ:=NOW();BEGIN SELECT * INTO pay FROM public.payments WHERE order_id=p_order_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Ödeme bulunamadı.');END IF;IF pay.status='SUCCESS' AND pay.entitlement_applied_at IS NOT NULL THEN SELECT * INTO s FROM public.corporate_profiles WHERE id=pay.corporate_profile_id;RETURN jsonb_build_object('success',true,'purchased_boost_credits',COALESCE(s.purchased_boost_credits,0));END IF;IF pay.status<>'PENDING' OR pay.purpose<>'LISTING_BOOST' OR pay.entitlement_type<>'BOOST_CREDIT' OR pay.external_payment_id IS NULL THEN RETURN jsonb_build_object('success',false,'error','Boost ödemesi uygun değil.');END IF;SELECT * INTO pkg FROM public.packages WHERE id=pay.package_id;IF NOT FOUND OR pkg.code<>'LISTING_BOOST_24_HOUR' OR NOT pkg.active OR pkg.seller_type<>'CORPORATE' OR pkg.duration_days<>1 OR pay.amount<>pkg.price THEN RETURN jsonb_build_object('success',false,'error','Boost paketi doğrulanamadı.');END IF;SELECT * INTO s FROM public.corporate_profiles WHERE id=pay.corporate_profile_id AND owner_profile_id=pay.profile_id AND status='APPROVED' AND moderation_status='ACTIVE' FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Mağaza uygun değil.');END IF;UPDATE public.corporate_profiles SET purchased_boost_credits=purchased_boost_credits+1,boost_credits=monthly_boost_credits+purchased_boost_credits+1,updated_at=at WHERE id=s.id RETURNING * INTO s;UPDATE public.payments SET status='SUCCESS',paid_at=COALESCE(paid_at,at),entitlement_applied_at=at,processed_at=at WHERE id=pay.id;RETURN jsonb_build_object('success',true,'purchased_boost_credits',s.purchased_boost_credits);END $$;

-- Explicit publication functions preserve the latest property fields and lock one eligible credit.
CREATE OR REPLACE FUNCTION public.create_listing_with_credit(p_profile_id UUID,p_seller_type TEXT,p_corporate_profile_id UUID,p_listing JSONB,p_details JSONB,p_images JSONB DEFAULT '[]') RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE c public.listing_credits%ROWTYPE;l public.listings%ROWTYPE;s public.corporate_profiles%ROWTYPE;at TIMESTAMPTZ:=NOW();days INTEGER;BEGIN IF jsonb_typeof(p_images)<>'array' OR jsonb_array_length(p_images)<1 THEN RAISE EXCEPTION 'En az 1 fotoğraf gereklidir.';END IF;IF p_seller_type='CORPORATE' THEN SELECT * INTO s FROM public.corporate_profiles WHERE id=p_corporate_profile_id AND owner_profile_id=p_profile_id AND status='APPROVED' AND moderation_status='ACTIVE' AND subscription_status='ACTIVE' AND subscription_expires_at>at FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Kurumsal üyelik aktif değil.');END IF;SELECT * INTO c FROM public.listing_credits WHERE profile_id=p_profile_id AND corporate_profile_id=p_corporate_profile_id AND credit_type='CORPORATE' AND status='AVAILABLE' AND used_at IS NULL AND usage_scope IN('NEW_LISTING_ONLY','NEW_OR_REPUBLISH') ORDER BY CASE grant_source WHEN 'MEMBERSHIP_PLUS' THEN 0 ELSE 1 END,created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;days:=14;ELSE SELECT * INTO c FROM public.listing_credits WHERE profile_id=p_profile_id AND credit_type='INDIVIDUAL' AND status='AVAILABLE' AND used_at IS NULL AND usage_scope='NEW_OR_REPUBLISH' ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;days:=7;END IF;IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Uygun yayın hakkı bulunamadı.');END IF;INSERT INTO public.listings(public_id,listing_number,seller_profile_id,seller_type,corporate_profile_id,category,subcategory,title,description,price,offers_enabled,minimum_offer_amount,location,status,published_at,expires_at) VALUES(public.generate_listing_public_id(),p_listing->>'listing_number',p_profile_id,p_seller_type,CASE WHEN p_seller_type='CORPORATE' THEN p_corporate_profile_id END,p_listing->>'category',p_listing->>'subcategory',p_listing->>'title',p_listing->>'description',(p_listing->>'price')::BIGINT,COALESCE((p_listing->>'offers_enabled')::BOOLEAN,true),(p_listing->>'minimum_offer_amount')::BIGINT,NULLIF(p_listing->>'location',''),'ACTIVE',at,at+make_interval(days=>days)) RETURNING * INTO l;IF l.category='vehicle' THEN INSERT INTO public.vehicle_details(listing_id,vehicle_category,brand,model,plate,mileage,engine_upgrade,transmission_upgrade,brake_upgrade,turbo,subwoofer,trade_available,lock_level,alarm_level,anti_theft_level,engine_health,suspension,fuel_type,factory_price) VALUES(l.id,p_details->>'vehicle_category',COALESCE(p_details->>'brand',''),COALESCE(p_details->>'model',''),COALESCE(p_details->>'plate','LS-TEMP'),COALESCE((p_details->>'mileage')::INTEGER,0),COALESCE((p_details->>'engine_upgrade')::INTEGER,0),COALESCE((p_details->>'transmission_upgrade')::INTEGER,0),COALESCE((p_details->>'brake_upgrade')::INTEGER,0),COALESCE((p_details->>'turbo')::BOOLEAN,false),COALESCE((p_details->>'subwoofer')::BOOLEAN,false),COALESCE((p_details->>'trade_available')::BOOLEAN,false),(p_details->>'lock_level')::INTEGER,(p_details->>'alarm_level')::INTEGER,(p_details->>'anti_theft_level')::INTEGER,(p_details->>'engine_health')::INTEGER,NULLIF(p_details->>'suspension',''),NULLIF(p_details->>'fuel_type',''),(p_details->>'factory_price')::BIGINT);ELSE INSERT INTO public.property_details(listing_id,property_type,floor,room_count,room_number,furnished,alarm,market_value,furniture_value,building_type,balcony) VALUES(l.id,p_details->>'property_type',COALESCE((p_details->>'floor')::INTEGER,1),COALESCE(p_details->>'room_count','1+1'),(p_details->>'room_number')::INTEGER,COALESCE((p_details->>'furnished')::BOOLEAN,false),(p_details->>'alarm')::BOOLEAN,(p_details->>'market_value')::BIGINT,CASE WHEN COALESCE((p_details->>'furnished')::BOOLEAN,false) THEN (p_details->>'furniture_value')::BIGINT END,COALESCE(p_details->>'building_type','Normal'),COALESCE((p_details->>'balcony')::BOOLEAN,false));END IF;INSERT INTO public.listing_images(listing_id,storage_path,sort_order,is_cover,size_bytes) SELECT l.id,x->>'storage_path',COALESCE((x->>'sort_order')::SMALLINT,0),COALESCE((x->>'is_cover')::BOOLEAN,false),COALESCE((x->>'size_bytes')::INTEGER,0) FROM jsonb_array_elements(p_images)x;UPDATE public.listing_credits SET status='USED',used_listing_id=l.id,used_at=at WHERE id=c.id;RETURN jsonb_build_object('success',true,'listing',to_jsonb(l));END $$;

CREATE OR REPLACE FUNCTION public.republish_listing_with_credit(p_listing_id UUID,p_profile_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE l public.listings%ROWTYPE;c public.listing_credits%ROWTYPE;owner UUID;at TIMESTAMPTZ:=NOW();days INTEGER;BEGIN SELECT * INTO l FROM public.listings WHERE id=p_listing_id FOR UPDATE;IF NOT FOUND OR (l.status<>'EXPIRED' AND NOT(l.status='ACTIVE' AND l.expires_at<=at)) THEN RETURN jsonb_build_object('success',false,'error','İlan uygun değil.');END IF;IF l.seller_type='CORPORATE' THEN SELECT owner_profile_id INTO owner FROM public.corporate_profiles WHERE id=l.corporate_profile_id AND subscription_status='ACTIVE' AND subscription_expires_at>at AND moderation_status='ACTIVE';IF owner IS DISTINCT FROM p_profile_id THEN RETURN jsonb_build_object('success',false,'error','Kurumsal üyelik aktif değil.');END IF;SELECT * INTO c FROM public.listing_credits WHERE profile_id=p_profile_id AND corporate_profile_id=l.corporate_profile_id AND status='AVAILABLE' AND used_at IS NULL AND usage_scope='NEW_OR_REPUBLISH' ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;days:=14;ELSE IF l.seller_profile_id<>p_profile_id THEN RETURN jsonb_build_object('success',false,'error','Yetkiniz yok.');END IF;SELECT * INTO c FROM public.listing_credits WHERE profile_id=p_profile_id AND status='AVAILABLE' AND used_at IS NULL AND credit_type='INDIVIDUAL' AND usage_scope='NEW_OR_REPUBLISH' ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;days:=7;END IF;IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Yeniden yayınlama hakkı yok.');END IF;UPDATE public.listing_credits SET status='USED',used_listing_id=l.id,used_at=at WHERE id=c.id;UPDATE public.listings SET status='ACTIVE',published_at=at,expires_at=at+make_interval(days=>days),updated_at=at,is_featured=false,featured_until=NULL WHERE id=l.id RETURNING * INTO l;RETURN jsonb_build_object('success',true,'listing',to_jsonb(l));END $$;

CREATE OR REPLACE FUNCTION public.get_corporate_membership_summary(p_corporate_profile_id UUID) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT jsonb_build_object('active_package_code',c.active_package_code,'included_listing_credits',(SELECT count(*) FROM public.listing_credits WHERE corporate_profile_id=c.id AND grant_source='MEMBERSHIP_PLUS' AND status='AVAILABLE' AND used_at IS NULL),'included_boost_credits',(SELECT count(*) FROM public.corporate_boost_credits WHERE corporate_profile_id=c.id AND grant_source='MEMBERSHIP_PLUS' AND used_at IS NULL),'purchased_boost_credits',c.purchased_boost_credits) FROM public.corporate_profiles c WHERE c.id=p_corporate_profile_id$$;

CREATE OR REPLACE FUNCTION public.run_expiry_lifecycle() RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE at TIMESTAMPTZ:=NOW();l RECORD;s RECORD;el BIGINT:=0;es BIGINT:=0;blocked BIGINT:=0;frozen BIGINT:=0;closed BIGINT:=0;n BIGINT;tr JSONB;BEGIN FOR l IN SELECT id FROM public.listings WHERE status='ACTIVE' AND expires_at<=at ORDER BY expires_at,id FOR UPDATE SKIP LOCKED LOOP UPDATE public.listings SET status='EXPIRED',is_featured=false,featured_until=NULL,updated_at=at WHERE id=l.id AND status='ACTIVE' AND expires_at<=at;GET DIAGNOSTICS n=ROW_COUNT;IF n=1 THEN el:=el+1;SELECT public.close_offers_for_listing(l.id,'LISTING_EXPIRED') INTO n;closed:=closed+COALESCE(n,0);END IF;END LOOP;FOR s IN SELECT id FROM public.corporate_profiles WHERE subscription_status='ACTIVE' AND subscription_expires_at<=at ORDER BY subscription_expires_at,id FOR UPDATE SKIP LOCKED LOOP BEGIN tr:=public.transition_corporate_membership_listings(s.id,'FREEZE');UPDATE public.corporate_profiles SET subscription_status='EXPIRED',monthly_boost_credits=0,boost_credits=purchased_boost_credits,current_period_end=LEAST(COALESCE(current_period_end,subscription_expires_at),subscription_expires_at),updated_at=at WHERE id=s.id AND subscription_status='ACTIVE';UPDATE public.corporate_membership_periods SET ends_at=LEAST(ends_at,at) WHERE corporate_profile_id=s.id AND ends_at>at;GET DIAGNOSTICS n=ROW_COUNT;es:=es+1;frozen:=frozen+COALESCE((tr->>'transitioned_listings')::BIGINT,0);EXCEPTION WHEN OTHERS THEN blocked:=blocked+1;RAISE WARNING 'Corporate membership expiry deferred for %: %',s.id,SQLERRM;END;END LOOP;RETURN jsonb_build_object('success',true,'expired_listings',el,'expired_subscriptions',es,'blocked_subscriptions',blocked,'frozen_membership_listings',frozen,'closed_offers',closed);END $$;
REVOKE ALL ON TABLE public.corporate_membership_periods,public.corporate_boost_credits FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON TABLE public.corporate_membership_periods,public.corporate_boost_credits TO service_role;
REVOKE ALL ON FUNCTION public.apply_corporate_membership_period(UUID,TEXT,UUID,UUID),public.consume_corporate_boost(UUID,UUID,TEXT),public.complete_sanboard_payment(TEXT,TEXT),public.complete_sanboard_boost_payment(TEXT),public.grant_corporate_subscription(UUID,UUID),public.grant_corporate_subscription(UUID,UUID,TEXT),public.create_listing_with_credit(UUID,TEXT,UUID,JSONB,JSONB,JSONB),public.republish_listing_with_credit(UUID,UUID),public.get_corporate_membership_summary(UUID),public.run_expiry_lifecycle() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_corporate_membership_period(UUID,TEXT,UUID,UUID),public.consume_corporate_boost(UUID,UUID,TEXT),public.complete_sanboard_payment(TEXT,TEXT),public.complete_sanboard_boost_payment(TEXT),public.grant_corporate_subscription(UUID,UUID),public.grant_corporate_subscription(UUID,UUID,TEXT),public.create_listing_with_credit(UUID,TEXT,UUID,JSONB,JSONB,JSONB),public.republish_listing_with_credit(UUID,UUID),public.get_corporate_membership_summary(UUID),public.run_expiry_lifecycle() TO service_role;
NOTIFY pgrst,'reload schema';COMMIT;